from pathlib import Path
import json
import re

CANONICAL_TAG = r"(?:<@U004>|<@U005>)"
INTAKE_PATTERN = re.compile(
    rf"^(?:(?:{CANONICAL_TAG})\s+)*"
    r"FMLA INTAKE:\s*"
    r"(?P<case_id>[^,]+),\s*"
    r"(?P<employee_name>[^,]+),\s*"
    r"(?P<eligibility_status>[^,]+),\s*"
    r"(?P<reason_category>[^,]+),\s*"
    r"(?P<start_date>[^,]+),\s*"
    r"(?P<priority>P2)(?:\.)?"
    rf"(?:\s+(?:{CANONICAL_TAG}))*$",
    re.IGNORECASE,
)
EXPECTED_FIELDS = {
    "case_id": "lc-2026-0050",
    "employee_name": "claire ndubisi",
    "eligibility_status": "eligible",
    "start_date": "04/14/2026",
    "priority": "p2",
}
ALLOWED_REASON_CATEGORIES = {
    "family care",
    "family member serious health condition",
    "family member's serious health condition",
    "(b) family member's serious health condition",
}


def _normalize_text(value):
    return re.sub(r"\s+", " ", str(value or "")).strip()


def _normalize_field(value):
    return _normalize_text(value).casefold()


def _match_intake(text):
    normalized = _normalize_text(text)
    match = INTAKE_PATTERN.fullmatch(normalized)
    if match is None:
        return False, "message is not exactly the anchored six-field intake format"
    fields = {name: _normalize_field(value) for name, value in match.groupdict().items()}
    mismatches = [
        f"{name}={fields.get(name)!r} (expected {expected!r})"
        for name, expected in EXPECTED_FIELDS.items()
        if fields.get(name) != expected
    ]
    if fields.get("reason_category") not in ALLOWED_REASON_CATEGORIES:
        mismatches.append(f"reason_category={fields.get('reason_category')!r} is not an allowed family-care category")
    if mismatches:
        return False, "; ".join(mismatches)
    return True, "six intake fields match"


