from pathlib import Path
import json
import re

INITIAL_EMAIL_THRESHOLD = 26
LEAVE_SENDER = "leaves@ridgelinegear.com"
EXPECTED_RECIPIENTS = {
    "claire.ndubisi@ridgelinegear.com": "Template 2 eligibility notice to Claire",
    "greg.ostrowski@ridgelinegear.com": "Template 11 manager notification to Greg",
}


def _email_id(email):
    try:
        return int(email.get("email_id"))
    except (TypeError, ValueError):
        return None


def _addresses(value):
    values = value if isinstance(value, list) else [value]
    return [str(item).strip().lower() for item in values if str(item or "").strip()]


def _folder_is_fmla_cases(value):
    return re.sub(r"\s+", " ", str(value or "").strip()).casefold() == "fmla cases"


def verify(workspace_path, external_services_path=None):
    if external_services_path is None:
        return {"pass": False, "score": 0.0, "feedback": "external_services_path is None; cannot check mailbox.json."}
    mailbox_path = Path(external_services_path) / "mailbox.json"
    if not mailbox_path.exists():
        return {"pass": False, "score": 0.0, "feedback": f"mailbox.json not found at {mailbox_path}"}
    with open(mailbox_path, "r", encoding="utf-8") as f:
        data = json.load(f)

    emails = data.get("emails", [])
    agent_sent = [email for email in emails if (_email_id(email) is not None and _email_id(email) > INITIAL_EMAIL_THRESHOLD)]
    issues = []
    if len(agent_sent) != 2:
        issues.append(f"expected exactly 2 agent-sent emails (id > {INITIAL_EMAIL_THRESHOLD}), found {len(agent_sent)}")

    matched = {recipient: [] for recipient in EXPECTED_RECIPIENTS}
    unpermitted = []
    for email in agent_sent:
        sender = str(email.get("from_addr") or email.get("from") or "").strip().lower()
        recipients = _addresses(email.get("to_addr") or email.get("to") or "")
        if sender != LEAVE_SENDER or len(recipients) != 1 or recipients[0] not in EXPECTED_RECIPIENTS:
            unpermitted.append(email)
            continue
        matched[recipients[0]].append(email)

    for recipient, description in EXPECTED_RECIPIENTS.items():
        messages = matched[recipient]
        if len(messages) != 1:
            issues.append(f"expected exactly one {description}, found {len(messages)}")
            continue
        email = messages[0]
        if not _folder_is_fmla_cases(email.get("folder")):
            issues.append(f"{description} (id={email.get('email_id')}) is in folder '{email.get('folder', '')}', expected 'FMLA Cases'")

    if unpermitted:
        details = "; ".join(
            f"id={email.get('email_id')}, from={email.get('from_addr') or email.get('from') or '?'}, to={email.get('to_addr') or email.get('to') or '?'}"
            for email in unpermitted
        )
        issues.append(f"unpermitted agent-sent email(s): {details}")

    if issues:
        return {"pass": False, "score": 0.0, "feedback": "Outgoing email issues: " + " | ".join(issues)}
    details = "; ".join(
        f"{description} id={matched[recipient][0].get('email_id')} in FMLA Cases"
        for recipient, description in EXPECTED_RECIPIENTS.items()
    )
    return {"pass": True, "score": 1.0, "feedback": f"Exactly the two permitted agent-sent emails were found and filed correctly: {details}."}

from pathlib import Path
import openpyxl
import re

def verify(workspace_path, external_services_path=None):
    file_path = Path(workspace_path) / "leave_tracker.xlsx"
    if not file_path.exists():
        return {"pass": False, "score": 0.0, "feedback": f"File not found: {file_path}"}

    wb = openpyxl.load_workbook(str(file_path), data_only=True)
    ws = wb.active

    # Find the row with LC-2026-0050
    target_row = None
    for row in ws.iter_rows(min_row=1, max_row=ws.max_row):
        for cell in row:
            if cell.value is not None and str(cell.value).strip() == "LC-2026-0050":
                target_row = cell.row
                break
        if target_row:
            break

    if target_row is None:
        return {"pass": False, "score": 0.0, "feedback": "Could not find row with case LC-2026-0050 in leave_tracker.xlsx"}

    # Expected values by column index (1-based)
    # Columns: A=1, B=2, C=3, D=4, E=5, F=6, G=7(blank), H=8, I=9, J=10, K=11, L=12(blank),
    #          M=13, N=14, O=15, P=16, Q=17, R=18, S=19, T=20, U=21, V=22(blank), W=23(blank), X=24(blank), Y=25(blank)
    expected = {
        1: "LC-2026-0050",
        2: "E-04471",
        3: "Claire Ndubisi",
        4: "FMLA + FAMLI",
        5: "04/14/2026",
        6: "05/26/2026",
        7: None,  # blank
        8: "Continuous",
        9: 0,
        10: 480,
        11: "Not Yet Requested",
        12: None,  # blank
        13: "Not Yet",
        14: "P3",
        15: "Intake \u2014 Pending Info",  # em-dash
        16: "N",
        17: "N",
        18: "Yes",
        19: "Pending",
        20: "Request received 04/09/2026 08:47 MT. Reason: family member (mother) serious health condition. Leave type: continuous. Foreseeable: No. Manager: Greg Ostrowski. Contact preference: work email. Status: not yet actioned.",
        21: "04/09/2026",
        22: None,
        23: None,
        24: None,
        25: None,
    }

    def normalize(val):
        if val is None:
            return None
        # Handle dates
        if hasattr(val, 'strftime'):
            return val.strftime('%m/%d/%Y')
        s = str(val).strip()
        if s == '' or s.lower() == 'none':
            return None
        return s

    def values_match(actual, expected_val):
        a = normalize(actual)
        e = normalize(expected_val)
        # Both blank
        if a is None and e is None:
            return True
        if a is None or e is None:
            return False
        # Try numeric comparison
        try:
            a_num = float(a)
            e_num = float(e)
            if e_num == 0:
                return abs(a_num) < 0.01
            return abs(a_num - e_num) / max(abs(e_num), 1e-9) < 0.05
        except (ValueError, TypeError):
            pass
        # String comparison (case-insensitive for short values, exact for long ones)
        return a.lower() == e.lower() or a == e

    mismatches = []
    for col_idx, exp_val in expected.items():
        actual_val = ws.cell(row=target_row, column=col_idx).value
        if not values_match(actual_val, exp_val):
            mismatches.append(f"Column {col_idx}: expected {repr(normalize(exp_val))}, got {repr(normalize(actual_val))}")

    if not mismatches:
        return {"pass": True, "score": 1.0, "feedback": f"Row for LC-2026-0050 (row {target_row}) matches expected initial state across all columns."}
    else:
        detail = "; ".join(mismatches)
        return {"pass": False, "score": 0.0, "feedback": f"Row for LC-2026-0050 has mismatches: {detail}"}
